mapper.select:
select sdc.id, sdc.user_id, sdc.card_user_id, sdc.seat_id, sdc.consumption_date, sdc.status, sdc.check_in_time, sdc.create_time, ss.seat_num, sr.room_name, sc.card_title, su.nickname, su.phone from sr_day_card_consumption sdc left join sr_seat ss on ss.seat_id = sdc.seat_id left join sr_room sr on sr.room_id = ss.room_id left join sr_card_user scu on scu.id = sdc.card_user_id left join sr_card sc on sc.id = scu.card_id left join sr_user su on su.user_id = sdc.user_id
(sdc.del_flag is null or sdc.del_flag = '0')
and sdc.consumption_date >= #{beginDate}
and sdc.consumption_date <= #{endDate}
and su.nickname like concat('%', #{nickname}, '%')
and sdc.status = #{status}
and ss.seat_num = #{seatNum}
order by sdc.consumption_date desc, sdc.create_time desc
